function Login(n){var t={};t.UserName=$("#username").val();t.UserPassword=$("#password").val();t.DefaultClientId=DefaultClientId;Common.Ajax("POST",n,JSON.stringify(t),"json",LoginHandler)}function LoginHandler(n){if(n.Message=="Invalid Credentials"&&alert("Invalid Credentials"),n.HasError==!0&&alert(n.Message),n.HasError==!1){console.log(n);var t={};t=n.Data.webLogin;console.log(t);sessionStorage.setItem("UserId",t.UserId);sessionStorage.setItem("ResturantId",t.ResturantId);sessionStorage.setItem("UserName",t.UserName);sessionStorage.setItem("RestaurantShortName",t.RestaurantShortName);sessionStorage.setItem("RestaurantName",t.RestaurantName);window.location="../Dinein/Dinein"}}function SessionHandler(n){console.log(n);n=="success"&&(window.location="../Dinein/Dinein")}var url;$(document).ready(function(){$.ajax({url:"../data.txt",async:!1,cache:!1,dataType:"text",success:function(n){url=n}});$("#bttnLogin").click(function(){Login(url+"SignInWebApp")})});